//设置服务器
function set_server() {
    putLoginInfo(JSON.stringify(result))
    let zdyserver;
    let base_url = getArgument(''server'')|| host[0];
    try {
        zdyserver = String(result[''自定义服务器(可不填)'']);
        if (zdyserver.includes(''http'')) {
            setArgument(''server'', zdyserver);
            if (getKey(String(cookie.getCookie(base_url)))) {
                let cookies = cookie.getCookie(base_url)
                try {
                    cookie.removeCookie(base_url)
                } catch (e) {}
                cookie.setCookie(zdyserver, cookies)
            }
            java.toast(`\n\n当前服务器为自定义服务器\n${zdyserver}\n\n切换服务器请先清空服务器地址中的数据`);
        } else {
            zdyserver = '''';
        }
    } catch (error) {
        zdyserver = '''';
    }
    if (!zdyserver) {
        const servers = host
        const currentServer = getArgument(''server'') || '''';
        const currentIndex = servers.indexOf(currentServer);

        const nextIndex = currentIndex >= 0 ? (currentIndex + 1) % servers.length : 0;
        const nextServer = servers[nextIndex];

        setArgument(''server'', nextServer);
        if (getKey(String(cookie.getCookie(currentServer)))) {
            let cookies = cookie.getCookie(currentServer)
            try {
                cookie.removeCookie(currentServer)
            } catch (e) {}
            cookie.setCookie(nextServer, cookies)
        }
        java.longToast(`\n\n服务器【${nextIndex+1}】：${nextServer}`);
    }
}

//获取音色
var tone_id = getArgument(''tone_id'');

function get_tone_id(arg) {
    var datadist = {
        "0": "默认音色",
        "-1": "阅读模式",
        "-2": "漫画模式",
        "51": "多人发音",
        "1": "甜美少女",
        "2": "清亮青叔",
        "5": "开朗青年",
        "6": "温柔淑女",
        "4": "成熟大叔",
        "74": "大叔升级",
        "30": "优雅御姐"
    };
    var tone_id = datadist[arg] || arg;
    var tishi = ''\n\n当前音色：'' + tone_id;
    java.toast(tishi);
}


//设置来源
function set_source(sources) {
    let zdysources = String(result[''自定义搜索源(多个用英文,分割)''] || '''');
    if (zdysources.length > 1 && zdysources != ''undefined'') {
        java.toast(''\n\n请先清空自定义源再设置'');
    } else {
        setArgument(''sources'', sources);
        set_media(''小说'');
        java.toast(`\n\n当前来源已切换为:\n${sources}\n\n切换后请重新搜索`);
    }
}

// 设置简介
function set_info() {
    var info = getArgument(''info'');
    if (info == ''off'') {
        setArgument(''info'', ''on'');
        java.toast(''\n\n已恢复详情页详细简介'');
    } else {
        setArgument(''info'', ''off'');
        java.toast(''\n\n已精简详情页简介'');
    }
}

// 番茄段评
function paracomment() {
    var fqpara = getArgument(''fqpara'');
    if (fqpara != ''on'') {
        setArgument(''fqpara'', ''on'');
        java.longToast("\n\n段评已开启\n\n长按刷新段后面的图片即可\n\n如果图片不显示，刷新无反应\n请更新测试版阅读app");
    } else {
        setArgument(''fqpara'', ''off'');
        java.longToast(''\n\n段评已关闭'');
    }
}

// 强制搜索被禁用的源
function disabledSources() {
    var disabled_sources = getArgument(''disabled_sources'');
    if (disabled_sources == ''1'') {
        setArgument(''disabled_sources'', ''0'');
        java.longToast(''\n\n强制搜索禁用的源已关闭'');
    } else {
        setArgument(''disabled_sources'', ''1'');
        setArgument(''sources'', ''全部'');
        java.longToast("\n\n强制搜索禁用的源已开启\n\n注意：开启后搜索时间会变长！");
    }
}

// 我要推荐
function put_book() {
    java.startBrowserAwait(getArgument(''server'')|| host[0] + ''/put_book'', ''我来推荐'');
}


