 else {\n        html = java.ajax(url);\n    }\n    java.log(''dddddddddddddddddddddddddddd'')\n    java.log(html);\n    if (html.includes(\"Just a moment...\") && sources == ''69书吧'' && book.durChapterIndex === chapter.index) {\n        cookie.removeCookie(''https://www.69shuba.com'');\n        java.longToast(''需要真人验证，请进入任意书籍详情页过验证'');\n        html = java.startBrowserAwait(url, \"需要真人验证，请进入任意书籍详情页过验证\").body();\n        java.log(''cscscscs'')\n        java.log(html);\n    }\n};\nlet content = \"\";\nlet data;\n//let tone_id = getArguments(source.getVariable(), \"tone_id\");\nlet tone_id = varia1;\nif (tone_id == '''') {\n    tone_id = ''4'';\n}\nlet base_url = getArguments(source.getVariable(), \"server\")|| host[0];\nlet fqpara = getArguments(source.getVariable(), \"fqpara\");\nlet close_img = getArguments(source.getVariable(), \"close_img\");\nlet device, device_type;\ntry {\n    device = java.deviceID();\n    device_type = \"苹果\";\n} catch (e) {\n    try {\n        device = java.androidId();\n        device_type = \"安卓\";\n    } catch (e) {\n        device = \"\";\n        device_type = \"安卓\";\n    }\n}\n\nlet qtcookie = cookie.getCookie(base_url);\ntry {\n\t   let device2 = String(cookie.getKey(base_url, \"device\"));\n\t   if (!device2){\n\t   \tdevice2 = device;\n\t   \t}\n    qtcookie = `qttoken=${String(cookie.getKey(base_url, \"qttoken\"))}; deviceId=${device2};`\n} catch (e) {java.log(e)}\n\nvar params = {\n    html: html,\n    item_id: item_id,\n    source: sources,\n    tab: tab,\n    tone_id: tone_id,\n    variable: varia,\n    version: ''4.11.5.1''\n};\n\nvar content_url = ''/content'';\nif ((sources == \"番茄\" || sources == \"七猫\" || sources == \"塔读\" || sources == \"QQ阅读\" || sources == \"svip_QQ阅读\") && fqpara && tab == \"小说\") {\n    content_url = ''/content?review=1'';\n}\n\n//var signInfo = generateComplexSignature(''POST'', content_url, {}, APP_SECRET, params);\n\n\n//var signedParams = copyObject(params);\n//signedParams.timestamp = signInfo.timestamp;\n//signedParams.nonce = signInfo.nonce;\n//signedParams.sign = signInfo.sign;\n\n\nvar op = {\n    method: \"POST\",\n    body: JSON.stringify(params),\n    headers: {\n        cookie: qtcookie,\n        ''Content-Type'': ''application/json''\n    }\n};\n\nop = JSON.stringify(op);\njava.log(op);\njava.log(cookie.getCookie(base_url))\ndata = java.ajax(base_url + content_url + `,${op}`);\ntry {\n    data = JSON.parse(data);\n    if (data.msg) {\n        java.toast(data.msg);\n    }\n} catch (e) {}\ncontent = data.content\n\nif (close_img == ''on'') {\n\tcontent = removeAllImgTags(content);\n\t}\n\nif ((sources == \"番茄\" || sources == \"七猫\" || sources == \"塔读\" || sources == \"QQ阅读\" || sources == \"svip_QQ阅读\") && fqpara == \"on\" && tab == \"小说\") {\n    var sdtoken;\n    try {\n        var loginInfoMap = source.getLoginInfoMap ? source.getLoginInfoMap() : {};\n        sdtoken = String(loginInfoMap[''手动填写番茄token(可不填)''] || '''');\n    } catch (e) {\n        sdtoken = '''';\n    }\n    var rawCookie = getFanqieCookie() || sdtoken;\n    var match = rawCookie.match(/sessionid=[^;]+/);\n    var fqcookie = match ? match[0] : '''';\n    var fqssionid = '''';\n    if (!fqcookie) {} else {\n        fqssionid = getSessionId(fqcookie)\n    }\n    content = content\n        .replace(/ident=\"/g, ''ident=\"'' + base_url)\n        .replace(/book_id=/g, ''book_id='' + book_id + ''&ssionid='' + fqssionid);\n    if (device_type == \"苹果\") {\n        content = paraForiOS(content, sources);\n    } else {\n        content = paraForAndroid(content, sources,islyc);\n    }\n}\ndata = JSON.stringify({\n    content: content,\n});\nif (device_type == \"安卓\" && (tab == \"短剧\" || tab == \"视频\" || sources.includes(''毒舌影视'') || sources.includes(''NT动漫''))) {\n    data = {\n        content: `【右上角刷新】开启播放(下一集请切换下一章刷新)\\n播放直链：\\n${content}`,\n    };\n    data = JSON.stringify(data);\n    if (book.durChapterIndex === chapter.index) {\n        let video_url = `${base_url}/online_video?book_id=${book_id}&source=${sources}&tab=${tab}`;\n        if (sources.includes(''毒舌影视'') || sources.includes(''NT动漫'')) {\n            video_url = content;\n        };\n        java.startBrowser(video_url, title);\n        java.toast(\"正在加载视频...\");\n    }\n\n}\ndata;\n</js>$.content"}', NULL, 0, 0, 0);

