INSERT INTO "books" VALUES ('path:C:\Users\JUHAI-ZK\AppData\Roaming\com.zkingz.reader\Books/悟空传.txt', 'path:C:\Users\JUHAI-ZK\AppData\Roaming\com.zkingz.reader\Books/悟空传.txt', 'local', '悟空传.txt', '悟空传', '今何在', NULL, NULL, NULL, NULL, '纷纷落叶飘向大地，白雪下种子沉睡，一朵花开了又迅速枯萎，在流转的光的阴影中，星图不断变幻，海水中矗起高山，草木几百代的荣枯，总有一片片的迎风挺立，酷似它们的祖先。
    怎能忘了西游？', NULL, 'utf-8', 4, 0, NULL, 0, 1779517348712, 0, 0, NULL, 0, 0, 1779517348712, NULL, 1, 0, 0, NULL, NULL, 0, 0, 0);
