-- ----------------------------
-- View structure for BookSourcePart
-- ----------------------------
DROP VIEW IF EXISTS "BookSourcePart";
CREATE VIEW "BookSourcePart" AS SELECT bookSourceUrl, bookSourceName, bookSourceGroup, customOrder, enabled, enabledExplore,
      (loginUrl IS NOT NULL AND trim(loginUrl) <> '') AS hasLoginUrl,
      lastUpdateTime, respondTime, weight,
      (exploreUrl IS NOT NULL AND trim(exploreUrl) <> '') AS hasExploreUrl,
      eventListener, bookSourceType
    FROM book_sources;

